const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s);
const ui={health:$('#health-bar'),healthText:$('#health-text'),xp:$('#xp-bar'),xpText:$('#xp-text'),level:$('#level'),kills:$('#kills'),shards:$('#shards'),floor:$('#floor-number'),count:$('#enemy-count'),objective:$('#objective-title'),sub:$('#objective-sub'),toast:$('#toast'),potion:$('#potion-count')};
let W=0,H=0,dpr=1,scale=1,cam={x:0,y:0};
const MAP={w:1420,h:940};
let state='menu',last=0,player,enemies=[],particles=[],loot=[],decor=[],keys={},mouse={x:0,y:0},joystick={active:false,id:null,x:0,y:0},attackAnim=0,toastTimer=0,spawnTimer=0,portal=null;
let floor=1,kills=0,shards=0,potions=2,level=1,xp=0,xpNeed=40,upgradeShown=false,elapsed=0;
const upgrades=[
 {name:'HEMORRHAGE',icon:'✦',desc:'Your blade deals 25% more damage.',apply:p=>p.damage*=1.25},
 {name:'IRON WILL',icon:'◈',desc:'Increase maximum vitality by 30.',apply:p=>{p.maxHp+=30;p.hp+=30}},
 {name:'QUICKENED STEP',icon:'➤',desc:'Move 15% faster and dodge farther.',apply:p=>{p.speed*=1.15;p.dodgeSpeed*=1.1}},
 {name:'SOUL SIPHON',icon:'♜',desc:'Recover 4 vitality with every kill.',apply:p=>p.lifesteal+=4},
 {name:'WIDE ARC',icon:'⚔',desc:'Your attacks reach 20% farther.',apply:p=>p.range*=1.2},
 {name:'BLOOD PACT',icon:'♥',desc:'Deal 35% more damage, lose 10 vitality.',apply:p=>{p.damage*=1.35;p.hp=Math.max(1,p.hp-10)}}
];
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);canvas.style.width=W+'px';canvas.style.height=H+'px';scale=Math.min(W/MAP.w,H/MAP.h)*1.13;if(W<700)scale=Math.min(W/MAP.w,H/MAP.h)*1.04;}
addEventListener('resize',resize);resize();
function reset(){floor=1;kills=0;shards=0;potions=2;level=1;xp=0;xpNeed=40;elapsed=0;player={x:0,y:70,r:20,hp:100,maxHp:100,speed:240,dodgeSpeed:590,damage:26,range:105,attackCd:0,dodgeCd:0,dodgeT:0,dx:1,dy:0,invuln:0,lifesteal:0};enemies=[];particles=[];loot=[];portal=null;makeDecor();spawnWave();refreshUI();}
function makeDecor(){decor=[];let seed=34567+floor*93;const rnd=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};for(let i=0;i<34;i++){let x=(rnd()-.5)*(MAP.w-170),y=(rnd()-.5)*(MAP.h-150);if(Math.abs(x)<100&&Math.abs(y)<110)continue;decor.push({x,y,type:rnd()<.42?'pillar':rnd()<.6?'bones':'brazier',phase:rnd()*6.28});}}
function spawnWave(){let n=5+floor*2;for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,d=450+Math.random()*190;let type=Math.random()<(floor>1?.28:.2)?'brute':'wraith';enemies.push({x:Math.cos(a)*d,y:Math.sin(a)*d*.72,r:type==='brute'?25:18,type,hp:type==='brute'?88+floor*12:48+floor*8,maxHp:type==='brute'?88+floor*12:48+floor*8,speed:type==='brute'?68+floor*2:94+floor*3,damage:type==='brute'?18:12,attackCd:.3+Math.random(),hit:0,phase:Math.random()*6.28,dead:false});}portal=null;updateCount();ui.objective.textContent='CLEAR THE SANCTUM';ui.sub.textContent=`Defeat the restless dead · ${n} enemies`;}
function start(){reset();state='playing';$('#start-screen').classList.remove('visible');toast('THE DEAD HAVE AWAKENED');}
function refreshUI(){ui.health.style.width=Math.max(0,player.hp/player.maxHp*100)+'%';ui.healthText.textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;ui.xp.style.width=Math.min(100,xp/xpNeed*100)+'%';ui.xpText.textContent=`${xp} / ${xpNeed}`;ui.level.textContent=level;ui.kills.textContent=kills;ui.shards.textContent=shards;ui.floor.textContent=String(floor).padStart(2,'0');ui.potion.textContent=potions;}
function updateCount(){ui.count.textContent=enemies.filter(e=>!e.dead).length;}
function toast(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');toastTimer=2.2;}
function gainXP(n){xp+=n;while(xp>=xpNeed){xp-=xpNeed;level++;xpNeed=Math.round(xpNeed*1.35);showUpgrade();}refreshUI();}
function showUpgrade(){state='upgrade';upgradeShown=true;const options=[...upgrades].sort(()=>Math.random()-.5).slice(0,3);const box=$('#upgrade-options');box.innerHTML='';options.forEach(o=>{let b=document.createElement('button');b.className='upgrade-card';b.innerHTML=`<span class="upgrade-icon">${o.icon}</span><b>${o.name}</b><small>${o.desc}</small>`;b.onclick=()=>{o.apply(player);state='playing';$('#level-screen').classList.remove('visible');toast(o.name+' ACQUIRED');refreshUI()};box.appendChild(b)});$('#level-screen').classList.add('visible');}
function screenToWorld(sx,sy){let x=(sx-W/2)/scale+cam.x;let y=(sy-H/2)/(scale*.82)+cam.y;return{x,y};}
function attack(){if(state!=='playing'||player.attackCd>0)return;player.attackCd=.43;attackAnim=.3;let nearest=null,dist=Infinity;for(let e of enemies){if(e.dead)continue;let d=Math.hypot(e.x-player.x,(e.y-player.y)*.86);if(d<dist){dist=d;nearest=e}}if(nearest&&dist<player.range+nearest.r){let angle=Math.atan2(nearest.y-player.y,nearest.x-player.x);player.dx=Math.cos(angle);player.dy=Math.sin(angle);nearest.hp-=player.damage;nearest.hit=.18;burst(nearest.x,nearest.y,'#e1ba7c',8);if(nearest.hp<=0)killEnemy(nearest);}}
function killEnemy(e){if(e.dead)return;e.dead=true;kills++;shards+=1+Math.floor(Math.random()*2);if(player.lifesteal)player.hp=Math.min(player.maxHp,player.hp+player.lifesteal);gainXP(e.type==='brute'?18:12);loot.push({x:e.x,y:e.y,type:'shard',life:10});burst(e.x,e.y,e.type==='brute'?'#d18459':'#a789bd',18);updateCount();refreshUI();if(!enemies.some(a=>!a.dead)){portal={x:0,y:0,pulse:0};ui.objective.textContent='THE WAY IS OPEN';ui.sub.textContent='Step into the rift to descend';toast('THE SANCTUM FALLS SILENT');}}
function burst(x,y,color,n){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,s=30+Math.random()*190;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.25+Math.random()*.55,max:.8,size:2+Math.random()*4,color});}}
function drinkPotion(){if(state!=='playing'||potions<=0||player.hp===player.maxHp)return;potions--;player.hp=Math.min(player.maxHp,player.hp+45);burst(player.x,player.y,'#83bd79',20);toast('VITALITY RESTORED');refreshUI();}
function dodge(){if(state!=='playing'||player.dodgeCd>0)return;let dx=0,dy=0;if(keys.KeyW||keys.ArrowUp)dy--;if(keys.KeyS||keys.ArrowDown)dy++;if(keys.KeyA||keys.ArrowLeft)dx--;if(keys.KeyD||keys.ArrowRight)dx++;if(joystick.active){dx=joystick.x;dy=joystick.y}if(!dx&&!dy){dx=player.dx;dy=player.dy}let n=Math.hypot(dx,dy)||1;player.dx=dx/n;player.dy=dy/n;player.dodgeT=.24;player.dodgeCd=1.1;player.invuln=.32;burst(player.x,player.y,'#b89568',6);}
function finish(win){state='end';$('#end-screen').classList.add('visible');$('#end-title').textContent=win?'ASCENDED':'FALLEN';$('#end-eyebrow').textContent=win?'THE VAULT REMEMBERS':'THE DESCENT ENDS';$('#end-copy').textContent=win?'The sanctum is yours. For now.':'The vault keeps its secrets.';$('#result-kills').textContent=kills;$('#result-floor').textContent=floor-1;}
function nextFloor(){floor++;player.hp=Math.min(player.maxHp,player.hp+18);player.x=0;player.y=70;makeDecor();spawnWave();refreshUI();toast(`DESCENDING · FLOOR ${floor}`);}
function update(dt){if(state!=='playing')return;elapsed+=dt;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}player.attackCd=Math.max(0,player.attackCd-dt);player.dodgeCd=Math.max(0,player.dodgeCd-dt);player.dodgeT=Math.max(0,player.dodgeT-dt);player.invuln=Math.max(0,player.invuln-dt);let dx=0,dy=0;if(keys.KeyW||keys.ArrowUp)dy--;if(keys.KeyS||keys.ArrowDown)dy++;if(keys.KeyA||keys.ArrowLeft)dx--;if(keys.KeyD||keys.ArrowRight)dx++;if(joystick.active){dx=joystick.x;dy=joystick.y}let m=Math.hypot(dx,dy);if(m>1){dx/=m;dy/=m}if(m>.05){player.dx=dx;player.dy=dy}let speed=player.dodgeT>0?player.dodgeSpeed:player.speed;player.x+=dx*speed*dt;player.y+=dy*speed*dt;player.x=Math.max(-MAP.w/2+68,Math.min(MAP.w/2-68,player.x));player.y=Math.max(-MAP.h/2+65,Math.min(MAP.h/2-65,player.y));
if(portal){portal.pulse+=dt;let d=Math.hypot(player.x-portal.x,player.y-portal.y);if(d<67){nextFloor();return}}
for(let e of enemies){if(e.dead)continue;e.phase+=dt*2;e.hit=Math.max(0,e.hit-dt);e.attackCd-=dt;let ex=player.x-e.x,ey=player.y-e.y,d=Math.hypot(ex,ey)||1;if(d>player.r+e.r+20){e.x+=ex/d*e.speed*dt;e.y+=ey/d*e.speed*dt}else if(e.attackCd<=0){e.attackCd=e.type==='brute'?1.25:1.05;if(player.invuln<=0&&player.dodgeT<=0){player.hp-=e.damage;player.invuln=.45;burst(player.x,player.y,'#d8584b',9);refreshUI();if(player.hp<=0){player.hp=0;finish(false)}}}}
for(let p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.life-=dt}particles=particles.filter(p=>p.life>0);for(let l of loot)l.life-=dt;loot=loot.filter(l=>l.life>0);cam.x+=(player.x-cam.x)*Math.min(1,dt*4);cam.y+=(player.y-cam.y)*Math.min(1,dt*4);}
function draw(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);ctx.fillStyle='#171719';ctx.fillRect(0,0,W,H);let sc=scale;ctx.save();ctx.translate(W/2,H/2);ctx.scale(sc,sc*.82);ctx.translate(-cam.x,-cam.y);drawRoom();drawDecor();if(portal)drawPortal();loot.forEach(drawLoot);enemies.filter(e=>!e.dead).sort((a,b)=>a.y-b.y).forEach(drawEnemy);drawPlayer();drawParticles();ctx.restore();}
function poly(points,fill,stroke,lw=1){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.lineWidth=lw;ctx.strokeStyle=stroke;ctx.stroke()}}
function drawRoom(){let l=-MAP.w/2,t=-MAP.h/2,r=MAP.w/2,b=MAP.h/2;ctx.fillStyle='#111113';ctx.fillRect(l-250,t-250,MAP.w+500,MAP.h+500);let grd=ctx.createLinearGradient(0,t,0,b);grd.addColorStop(0,'#383432');grd.addColorStop(.5,'#302e2c');grd.addColorStop(1,'#282726');ctx.fillStyle=grd;ctx.fillRect(l,t,MAP.w,MAP.h);
// irregular stone floor blocks
for(let y=t;y<b;y+=82){for(let x=l;x<r;x+=112){let off=(Math.floor((y-t)/82)%2)*56;let xx=x+off;ctx.fillStyle=((Math.floor((xx-l)/112)+Math.floor((y-t)/82))%2===0)?'rgba(222,205,177,.023)':'rgba(0,0,0,.035)';ctx.fillRect(xx,y,108,78);ctx.strokeStyle='rgba(8,8,9,.19)';ctx.lineWidth=2;ctx.strokeRect(xx+1,y+1,106,76);ctx.beginPath();ctx.moveTo(xx+8,y+68);ctx.lineTo(xx+23,y+65);ctx.strokeStyle='rgba(198,180,157,.045)';ctx.lineWidth=1;ctx.stroke();}}
// boundary walls
ctx.fillStyle='#211f20';ctx.fillRect(l-18,t-20,MAP.w+36,23);ctx.fillRect(l-18,b-4,MAP.w+36,35);ctx.fillRect(l-20,t,24,MAP.h);ctx.fillRect(r-4,t,24,MAP.h);for(let x=l;x<r;x+=90){ctx.fillStyle='#433b35';ctx.fillRect(x,t-20,80,10);ctx.fillStyle='#1a191a';ctx.fillRect(x,b+3,80,9)}
// carved central pattern
ctx.save();ctx.globalAlpha=.16;ctx.strokeStyle='#c19a67';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,115,0,Math.PI*2);ctx.arc(0,0,93,0,Math.PI*2);for(let i=0;i<8;i++){let a=i*Math.PI/4;ctx.moveTo(Math.cos(a)*94,Math.sin(a)*94);ctx.lineTo(Math.cos(a)*114,Math.sin(a)*114)}ctx.stroke();ctx.restore();
// warm pools of light
for(let [x,y] of [[-MAP.w/2+100,-MAP.h/2+100],[MAP.w/2-100,-MAP.h/2+100],[-MAP.w/2+100,MAP.h/2-100],[MAP.w/2-100,MAP.h/2-100]]){let g=ctx.createRadialGradient(x,y,0,x,y,220);g.addColorStop(0,'rgba(194,126,60,.11)');g.addColorStop(1,'rgba(194,126,60,0)');ctx.fillStyle=g;ctx.fillRect(x-220,y-220,440,440)}}
function drawDecor(){for(let d of decor){if(d.type==='pillar'){ctx.fillStyle='#151415';ctx.beginPath();ctx.ellipse(d.x,d.y+13,42,26,0,0,Math.PI*2);ctx.fill();poly([[d.x-29,d.y-43],[d.x-24,d.y-64],[d.x+24,d.y-64],[d.x+29,d.y-43]],'#49413a','#171617',3);ctx.fillStyle='#5b5047';ctx.fillRect(d.x-25,d.y-43,50,45);ctx.fillStyle='#74675b';ctx.fillRect(d.x-29,d.y-47,58,8);ctx.fillStyle='#342e2b';ctx.fillRect(d.x-25,d.y-5,50,8);ctx.fillStyle='#85715d';ctx.fillRect(d.x-18,d.y-35,3,28)}else if(d.type==='bones'){ctx.save();ctx.translate(d.x,d.y);ctx.rotate(d.phase);ctx.fillStyle='#b9aa90';ctx.globalAlpha=.55;ctx.fillRect(-18,-3,36,6);ctx.beginPath();ctx.arc(-17,-2,4,0,7);ctx.arc(17,2,4,0,7);ctx.fill();ctx.restore()}else{let pulse=.7+Math.sin(elapsed*3+d.phase)*.18;ctx.fillStyle='#514237';ctx.fillRect(d.x-8,d.y-8,16,18);ctx.fillStyle='#d27b3e';ctx.beginPath();ctx.ellipse(d.x,d.y-14,6,12*pulse,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffd38b';ctx.beginPath();ctx.ellipse(d.x,d.y-16,2.4,6*pulse,0,0,Math.PI*2);ctx.fill();let g=ctx.createRadialGradient(d.x,d.y-14,0,d.x,d.y-14,70);g.addColorStop(0,'rgba(220,137,69,.15)');g.addColorStop(1,'rgba(220,137,69,0)');ctx.fillStyle=g;ctx.fillRect(d.x-70,d.y-84,140,140)}}}
function drawPortal(){let p=portal;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(Math.sin(p.pulse)*.05);let pulse=1+Math.sin(p.pulse*3)*.07;ctx.scale(pulse,pulse);for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(0,-4,45+i*11,25+i*6,p.pulse*.2+i*.7,0,Math.PI*2);ctx.strokeStyle=`rgba(205,163,99,${.8-i*.18})`;ctx.lineWidth=3-i*.5;ctx.stroke()}let g=ctx.createRadialGradient(0,-5,2,0,-5,54);g.addColorStop(0,'rgba(209,174,116,.5)');g.addColorStop(1,'rgba(79,64,100,0)');ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(0,-5,55,33,0,0,Math.PI*2);ctx.fill();ctx.restore()}
function shadow(x,y,rx,ry){ctx.fillStyle='rgba(0,0,0,.43)';ctx.beginPath();ctx.ellipse(x,y+5,rx,ry,0,0,Math.PI*2);ctx.fill()}
function drawPlayer(){let p=player;shadow(p.x,p.y,25,11);if(p.dodgeT>0){ctx.globalAlpha=.43;ctx.fillStyle='#c3a277';ctx.beginPath();ctx.ellipse(p.x-p.dx*25,p.y-p.dy*25,18,24,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}ctx.save();ctx.translate(p.x,p.y+Math.sin(elapsed*7)*1.2);if(p.invuln>0&&Math.floor(elapsed*18)%2)ctx.globalAlpha=.5;
// cape
poly([[-13,-18],[-18,9],[-8,21],[12,17],[16,-13]],'#49292a','#251b1b',2);poly([[-12,-17],[0,-25],[13,-16],[11,8],[-9,9]],'#71604c','#302821',2);ctx.fillStyle='#c6a575';ctx.beginPath();ctx.arc(0,-25,10,0,Math.PI*2);ctx.fill();ctx.fillStyle='#343233';ctx.beginPath();ctx.arc(0,-29,11,Math.PI,Math.PI*2);ctx.fill();ctx.fillRect(-9,-30,18,4);ctx.fillStyle='#d58c63';ctx.fillRect(3,-26,4,2);
// sword angled toward facing
ctx.save();ctx.translate(p.dx*11,p.dy*11-10);ctx.rotate(Math.atan2(p.dy,p.dx)+Math.PI/2);ctx.fillStyle='#523c2f';ctx.fillRect(-2,1,4,15);ctx.fillStyle='#bc9d69';ctx.fillRect(-7,1,14,3);poly([[-2,-1],[0,-24],[2,-1]],'#c8c1b2','#6e655a',1);ctx.restore();ctx.restore();if(attackAnim>0){attackAnim=Math.max(0,attackAnim-.016);ctx.save();ctx.translate(p.x,p.y-14);let a=Math.atan2(p.dy,p.dx);ctx.beginPath();ctx.arc(0,0,player.range*.78,a-.8,a+.8);ctx.strokeStyle=`rgba(238,207,150,${attackAnim/.3*.8})`;ctx.lineWidth=5;ctx.shadowColor='#dbad6c';ctx.shadowBlur=14;ctx.stroke();ctx.restore()}}
function drawEnemy(e){let bob=Math.sin(elapsed*4+e.phase)*2;shadow(e.x,e.y,e.r*1.18,e.r*.54);ctx.save();ctx.translate(e.x,e.y+bob);if(e.hit>0){ctx.globalAlpha=.75+Math.sin(e.hit*40)*.25}if(e.type==='wraith'){let g=ctx.createRadialGradient(0,-15,2,0,-8,32);g.addColorStop(0,'#bca1c6');g.addColorStop(.4,'#756283');g.addColorStop(1,'rgba(74,62,81,.1)');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(-17,5);ctx.quadraticCurveTo(-24,-22,0,-31);ctx.quadraticCurveTo(25,-19,18,5);ctx.lineTo(13,17);ctx.lineTo(5,10);ctx.lineTo(-2,19);ctx.lineTo(-10,10);ctx.closePath();ctx.fill();ctx.fillStyle='#edb77b';ctx.shadowColor='#efad71';ctx.shadowBlur=10;ctx.fillRect(-9,-17,5,3);ctx.fillRect(4,-17,5,3);ctx.shadowBlur=0;ctx.strokeStyle='#b696c2';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-12,10);ctx.lineTo(-15,23);ctx.moveTo(10,9);ctx.lineTo(14,22);ctx.stroke()}else{ctx.fillStyle='#382e2a';ctx.beginPath();ctx.ellipse(0,-7,22,25,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#635044';ctx.beginPath();ctx.ellipse(0,-13,19,21,0,0,Math.PI*2);ctx.fill();poly([[-17,-25],[-14,-38],[-5,-28],[0,-38],[6,-27],[16,-31],[14,-19]],'#77604d','#322823',2);ctx.fillStyle='#d27558';ctx.shadowColor='#e4674c';ctx.shadowBlur=8;ctx.fillRect(-10,-19,5,4);ctx.fillRect(5,-19,5,4);ctx.shadowBlur=0;ctx.fillStyle='#88715d';ctx.fillRect(-19,-8,5,15);ctx.fillRect(14,-8,5,15)}ctx.restore();if(e.hp<e.maxHp){ctx.fillStyle='#141313';ctx.fillRect(e.x-20,e.y-e.r-14,40,4);ctx.fillStyle=e.type==='brute'?'#b86e4e':'#ac8cbb';ctx.fillRect(e.x-20,e.y-e.r-14,40*Math.max(0,e.hp/e.maxHp),4)}}
function drawLoot(l){let z=1+Math.sin(elapsed*4+l.x)*.12;ctx.save();ctx.translate(l.x,l.y-15-Math.sin(elapsed*3+l.y)*4);ctx.rotate(elapsed*1.5);ctx.scale(z,z);ctx.fillStyle='#d9b477';ctx.shadowColor='#e2b46f';ctx.shadowBlur=13;ctx.beginPath();ctx.moveTo(0,-8);ctx.lineTo(6,0);ctx.lineTo(0,8);ctx.lineTo(-6,0);ctx.closePath();ctx.fill();ctx.restore()}
function drawParticles(){for(let p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}
function loop(ts){let dt=Math.min(.034,(ts-last)/1000||0);last=ts;update(dt);draw();requestAnimationFrame(loop)}requestAnimationFrame(loop);
$('#start-button').onclick=start;$('#restart-button').onclick=()=>{$('#end-screen').classList.remove('visible');start()};$('#pause-button').onclick=()=>{if(state==='playing'){state='paused';$('#pause-screen').classList.add('visible')}else if(state==='paused'){state='playing';$('#pause-screen').classList.remove('visible')}};$('#resume-button').onclick=()=>{$('#pause-screen').classList.remove('visible');state='playing'};$('#potion-button').onclick=drinkPotion;$('#dodge-button').onclick=dodge;$('#attack-button').onclick=attack;$('#mobile-attack').onclick=attack;$('#mobile-dodge').onclick=dodge;
addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Space'&&!e.repeat)dodge();if(e.code==='KeyQ'&&!e.repeat)drinkPotion();if(e.code==='Escape'){if(state==='playing')$('#pause-button').click();else if(state==='paused')$('#resume-button').click()}});addEventListener('keyup',e=>keys[e.code]=false);canvas.addEventListener('pointermove',e=>{mouse=screenToWorld(e.clientX,e.clientY)});canvas.addEventListener('pointerdown',e=>{if(state==='playing'&&e.pointerType==='mouse')attack()});
